import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_K": k},
        )
        for k in [16, 32, 64, 128, 256]
    ],
    key=["K"],
)
@triton.jit
def _gemv_kernel(
    a_ptr,
    b_ptr,
    c_ptr,
    K,
    stride_am,
    BLOCK_K: tl.constexpr,
):
    row = tl.program_id(0)
    a_row_ptr = a_ptr + row * stride_am

    acc = tl.zeros((BLOCK_K,), dtype=tl.float32)

    for k in range(0, K, BLOCK_K):
        offs_k = k + tl.arange(0, BLOCK_K)
        mask = offs_k < K
        a_vals = tl.load(a_row_ptr + offs_k, mask=mask, other=0.0)
        b_vals = tl.load(b_ptr + offs_k, mask=mask, other=0.0)
        acc += a_vals.to(tl.float32) * b_vals.to(tl.float32)

    result = tl.sum(acc)
    tl.store(c_ptr + row, result.to(tl.bfloat16))


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        M, K = A.shape
        C = torch.empty(M, device=A.device, dtype=A.dtype)

        B_flat = B.view(-1).contiguous()

        grid = (M,)
        _gemv_kernel[grid](
            A,
            B_flat,
            C,
            K,
            A.stride(0),
        )
        return C.view(M, 1)
